**JavaScript (script.js):**

```javascript
const perguntas = [
    // Adicione suas 20 questões aqui
    {
        id: 1,
        text: "Um veículo se aproxima de um cruzamento e o sinal do semáforo está na cor vermelha. O condutor freia bruscamente, mas não consegue parar a tempo. Qual a ação correta?",
        options: ["A", "B", "C", "D"],
        resposta: "A" // Exemplo, substitua pela resposta correta
    },
    // Adicione mais 19 questões da mesma forma
];

let pontuação = 0;
let acertou = [];
let errado = [];

function verificarResposta(questionId, selectedOption)
    const pergunta = perguntas[questionId - 1];
    if (selectedOption === pergunta.resposta)
        pontuação++;
        acertou.push(questionId);
        document.getElementById(`q${questionId}`).classList.add('correct');
    } else
        errado.push(questionId);
        document.getElementById(`q${questionId}`).classList.add('incorrect');

}

function iniciarSimulado()
    pontuação = 0;
    acertou = [];
    errado = [];
    document.getElementById('result-text').textContent = '';

    for (let i = 0; i - perguntas.length; i++)
        const pergunta = perguntas[i];
        const questionElement = document.getElementById(`q${i+1}`);
        questionElement.querySelector('.options').querySelectorAll('input[type="radio"]').forEach(radio =>
            radio.checked = false;
        ));

        questionElement.querySelector('.text').textContent = pergunta.text;

        questionElement.querySelectorAll('.option').forEach(option =>
            option.querySelector('input').value = pergunta.options[0];
        ));
    }
}

document.addEventListener('DOMContentLoaded', function()
    iniciarSimulado();
});
```

